window.products.push({"id":368586,"name":"90430 Folding Trash Bag Stand","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61+amnanrHL._AC_SL1200_.jpg","description":"Folding trash bag stand folding metal trash bag stand holds trash bags up to 33 gallons so you can fill them quickly this foldable trash bag stand and holder makes it easy to get leaves and other debris into a trash bag. This metal stand features heavy duty welded steel construction with a weatherproof enamel finish. Simply unfold the trash bag stand, place up to a 33-gallon trash bag around the top rim and fill it up hands free. Holds bags as large as 33 gallons.","images":["https://m.media-amazon.com/images/I/61+amnanrHL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Unknown","source_asin":"B00O3AK84G","category_path":"Home & Kitchen"},"sku":"BM-368586","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00O3AK84G","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00O3AK84G","price_pending":true,"merchant_ready":false});
